//! Central 95% chi-square intervals for sensor innovation evidence.
//! Quantiles generated by scipy.stats.chi2.ppf([0.025, 0.975], dof).
#[derive(Clone, Copy, Default)]
pub struct InnovationStats {
    pub count: usize,
    pub hits: usize,
    pub sum: f64,
}
impl InnovationStats {
    pub fn record(&mut self, value: f64, dof: usize) {
        self.count += 1;
        self.hits += usize::from(in_interval(value, dof));
        self.sum += value;
    }
}
pub fn in_interval(value: f64, dof: usize) -> bool {
    if !value.is_finite() || dof == 0 {
        return false;
    }
    INTERVALS
        .get(dof - 1)
        .is_some_and(|&(lo, hi)| value >= lo && value <= hi)
}
