#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn rejected_and_nonfinite_innovations_stay_in_the_denominator() {
        let mut stats = InnovationStats::default();
        for value in [6.0, 1000.0, f64::NAN] {
            stats.record(value, 6);
        }
        assert_eq!(stats.count, 3);
        assert_eq!(stats.hits, 1);
        assert!(!in_interval(1.0, 0));
        assert!(!in_interval(1.0, 65));
    }
}
